const input = $('When Executed by Another Workflow').first().json;
const row = $input.first().json;

if (!row?.catalog_json) {
  return [{ json: { valid: false, errors: [`No catalog for customer ${input.customerId ?? input.customer_id}`] } }];
}

const catalog = JSON.parse(row.catalog_json);

// Invariant: sku is the pricing key, so a duplicate sku would make the lookup
// below silently price the order from an arbitrary row.
const skuCounts = new Map();
for (const p of catalog) skuCounts.set(p.sku, (skuCounts.get(p.sku) ?? 0) + 1);
const duplicateSkus = [...skuCounts].filter(([, n]) => n > 1).map(([sku]) => sku);
if (duplicateSkus.length) {
  return [{ json: { valid: false, errors: [`Catalog is invalid: duplicate sku(s) ${duplicateSkus.join(', ')}`] } }];
}

const bySku = new Map(catalog.map(p => [p.sku, p]));
const errors = [];

// Pricing is keyed on sku. `product_number` is the key the CRM product id gets
// resolved from: it comes from the order's `productNumber` field and has to
// match productNumber on the catalog entry for the line's sku. That catalog
// check is what stops a caller pairing a cheap sku with a product it was not
// priced as.
const PRODUCT_NUMBER_PATTERN = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/;

// Consolidate duplicate skus so volume tiers apply to the true total
const qtyBySku = new Map();
const productNumberBySku = new Map();
for (const [i, li] of (input.lineItems ?? []).entries()) {
  const product = bySku.get(li.sku);
  if (!product) {
    errors.push(`Line ${i + 1}: unknown sku '${li.sku}'`);
    continue;
  }
  if (!Number.isInteger(li.quantity) || li.quantity < 1) {
    errors.push(`Line ${i + 1}: invalid quantity '${li.quantity}'`);
    continue;
  }

  const productNumber = String(li.productNumber ?? '').trim();
  if (!productNumber) {
    errors.push(`Line ${i + 1}: productNumber is required`);
    continue;
  }
  if (!PRODUCT_NUMBER_PATTERN.test(productNumber)) {
    errors.push(`Line ${i + 1}: productNumber '${productNumber}' is not a supported format`);
    continue;
  }

  const catalogProductNumber = String(product.productNumber ?? '').trim();
  if (!catalogProductNumber) {
    errors.push(`Line ${i + 1}: catalog entry for sku '${li.sku}' has no productNumber`);
    continue;
  }
  if (productNumber !== catalogProductNumber) {
    errors.push(`Line ${i + 1}: productNumber '${productNumber}' does not match the catalog for sku '${li.sku}' (expected '${catalogProductNumber}')`);
    continue;
  }

  qtyBySku.set(li.sku, (qtyBySku.get(li.sku) ?? 0) + li.quantity);
  productNumberBySku.set(li.sku, productNumber);
}
if (!qtyBySku.size && !errors.length) errors.push('Order has no line items');

const line_items = [...qtyBySku].map(([sku, quantity]) => {
  const p = bySku.get(sku);
  const tier = p.pricing.tiers.find(t => t.upTo === null || quantity <= t.upTo);
  return {
    sku,
    product_number: productNumberBySku.get(sku),
    title: p.title,
    quantity,
    unit_amount_cents: tier.unitAmountCents,
    line_total_cents: quantity * tier.unitAmountCents,
    lead_time: p.leadTime
  };
});

return [{
  json: {
    valid: errors.length === 0,
    errors,
    currency: 'USD',
    line_items,
    total_cents: line_items.reduce((s, l) => s + l.line_total_cents, 0)
  }
}];
